CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','suspended','disabled')),email_verified_at timestamptz,verify_token text,reset_token text,reset_expires timestamptz,is_platform_admin boolean DEFAULT false,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS workspaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,status text DEFAULT 'active',created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS workspace_members(workspace_id uuid REFERENCES workspaces ON DELETE CASCADE,user_id uuid REFERENCES users ON DELETE CASCADE,role text NOT NULL CHECK(role IN('owner','member')),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS wa_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,waba_id text NOT NULL,phone_number_id text UNIQUE NOT NULL,display_number text,verified_name text,status text DEFAULT 'pending',token_enc text NOT NULL,quality text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,phone text NOT NULL,name text,email text,attrs jsonb DEFAULT '{}',consent_status text DEFAULT 'none' CHECK(consent_status IN('none','opted_in')),created_at timestamptz DEFAULT now(),UNIQUE(workspace_id,phone));
CREATE TABLE IF NOT EXISTS consent_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,contact_id uuid REFERENCES contacts ON DELETE CASCADE,action text NOT NULL,source text,purpose text DEFAULT 'marketing',evidence text,created_by uuid,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS suppressions(workspace_id uuid NOT NULL,phone text NOT NULL,reason text,created_at timestamptz DEFAULT now(),PRIMARY KEY(workspace_id,phone));
CREATE TABLE IF NOT EXISTS groups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,name text NOT NULL,UNIQUE(workspace_id,name));
CREATE TABLE IF NOT EXISTS group_members(group_id uuid REFERENCES groups ON DELETE CASCADE,contact_id uuid REFERENCES contacts ON DELETE CASCADE,PRIMARY KEY(group_id,contact_id));
CREATE TABLE IF NOT EXISTS import_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,filename text,total int,imported int,duplicates int,invalid int,errors jsonb,created_by uuid,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,wa_account_id uuid,name text NOT NULL,language text,status text,category text,components jsonb,UNIQUE(workspace_id,name,language));
CREATE TABLE IF NOT EXISTS campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,wa_account_id uuid,name text NOT NULL,type text,body text,template_id uuid,media_id uuid,status text DEFAULT 'draft',scheduled_at timestamptz,created_by uuid,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS campaign_recipients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,campaign_id uuid REFERENCES campaigns ON DELETE CASCADE,contact_id uuid,phone text,status text DEFAULT 'queued',attempts int DEFAULT 0,provider_message_id text,error_code text,error_text text,sent_at timestamptz,delivered_at timestamptz,read_at timestamptz,UNIQUE(campaign_id,contact_id));
CREATE TABLE IF NOT EXISTS conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,wa_account_id uuid,contact_id uuid,status text DEFAULT 'open',unread int DEFAULT 0,last_inbound_at timestamptz,last_activity_at timestamptz DEFAULT now(),UNIQUE(wa_account_id,contact_id));
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,conversation_id uuid,wa_account_id uuid,contact_id uuid,direction text NOT NULL,type text,body text,media_ref text,provider_message_id text UNIQUE,status text,error text,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS webhook_events(event_id text PRIMARY KEY,payload jsonb,processed_at timestamptz,error text,received_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id bigserial PRIMARY KEY,workspace_id uuid,user_id uuid,action text NOT NULL,detail jsonb,created_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_contacts_ws ON contacts(workspace_id);
CREATE INDEX IF NOT EXISTS idx_recip_q ON campaign_recipients(campaign_id,status);
CREATE INDEX IF NOT EXISTS idx_msgs_conv ON messages(conversation_id,created_at);
ALTER TABLE campaigns ADD COLUMN IF NOT EXISTS params jsonb DEFAULT '[]';
ALTER TABLE campaigns ADD COLUMN IF NOT EXISTS media_url text;
ALTER TABLE campaigns ADD COLUMN IF NOT EXISTS audience jsonb DEFAULT '{}';
ALTER TABLE campaigns ADD COLUMN IF NOT EXISTS paused_reason text;
ALTER TABLE campaign_recipients ADD COLUMN IF NOT EXISTS next_attempt_at timestamptz DEFAULT now();
ALTER TABLE campaign_recipients ADD COLUMN IF NOT EXISTS claimed_at timestamptz;
ALTER TABLE messages ADD COLUMN IF NOT EXISTS campaign_recipient_id uuid;
CREATE TABLE IF NOT EXISTS plans(id text PRIMARY KEY,name text NOT NULL,price_inr int NOT NULL DEFAULT 0,monthly_messages int NOT NULL,max_contacts int NOT NULL,max_members int NOT NULL,max_senders int NOT NULL DEFAULT 1,active boolean DEFAULT true,sort int DEFAULT 0);
INSERT INTO plans(id,name,price_inr,monthly_messages,max_contacts,max_members,max_senders,sort) VALUES('trial','Free trial',0,200,500,2,1,0),('starter','Starter',999,2000,5000,3,1,1),('growth','Growth',3999,15000,50000,10,3,2) ON CONFLICT(id) DO NOTHING;
CREATE TABLE IF NOT EXISTS subscriptions(workspace_id uuid PRIMARY KEY REFERENCES workspaces ON DELETE CASCADE,plan_id text NOT NULL REFERENCES plans,status text NOT NULL DEFAULT 'trialing' CHECK(status IN('trialing','active','past_due','cancelled')),period_start timestamptz NOT NULL DEFAULT now(),period_end timestamptz NOT NULL DEFAULT now()+interval '14 days',provider text,provider_ref text,updated_at timestamptz DEFAULT now());
INSERT INTO subscriptions(workspace_id,plan_id) SELECT id,'trial' FROM workspaces ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),token_hash text UNIQUE NOT NULL,workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,email text NOT NULL,role text DEFAULT 'member',invited_by uuid,expires_at timestamptz NOT NULL,accepted_at timestamptz);
ALTER TABLE users ADD COLUMN IF NOT EXISTS failed_logins int DEFAULT 0;
ALTER TABLE users ADD COLUMN IF NOT EXISTS locked_until timestamptz;
ALTER TABLE webhook_events ADD COLUMN IF NOT EXISTS retries int DEFAULT 0;
